	@ParameterizedTest
	@ValueSource(strings = { "SNAPSHOT", "NONE", "SERIALIZABLE" })
	void closingOwnerClosesOutstandingGenericIteratorsBeforeNativeResources(String level) throws Exception {
		try (Fixture fixture = new Fixture("spoc,posc", false)) {
			IsolationLevel isolation = switch (level) {
			case "NONE" -> IsolationLevels.NONE;
			case "SERIALIZABLE" -> IsolationLevels.SERIALIZABLE;
			default -> IsolationLevels.SNAPSHOT;
			};
			SailDataset dataset = fixture.dataset(true, isolation);
			CloseableIteration<? extends Statement> rows = dataset.getStatements(S, P, null, G, null);
			ExecutorService closer = Executors.newSingleThreadExecutor();
			try {
				assertTrue(rows.hasNext());
				Future<?> close = closer.submit(dataset::close);
				// Detect a close deadlock while native read stamps and direct leases remain outstanding.
				close.get(10, TimeUnit.SECONDS);
				assertFalse(rows.hasNext());
				assertThrows(RuntimeException.class, () -> dataset.getStatements(S, P, null));
			} finally {
				rows.close();
				dataset.close();
				closer.shutdownNow();
			}
			assertThat(fixture.direct.snapshotMetrics().activeViews).isZero();
		}
	}

