	private static List<Statement> collect(CloseableIteration<? extends Statement> rows) {
		try (rows) {
			List<Statement> result = new ArrayList<>();
			while (rows.hasNext()) {
				Statement row = rows.next();
				// Detach through real RDF values before closing their dictionary snapshot.
				result.add(LegacySemanticScope.detached(row));
			}
			return result;
		}
	}

	private static List<Statement> expected(List<Statement> seed, NativeLmdbQuerySource source,
			LmdbSailStore backing, Resource subject, IRI predicate, Value object, Resource[] contexts) {
		List<Statement> result = new ArrayList<>();
		Resource[] requests = contexts.length == 0 ? new Resource[] { null } : contexts;
		for (Resource context : requests) {
			if (context != null && (context.isTripleTerm() || source.idOf(context) < 0L)) {
				continue;
			}
			long contextId = contexts.length == 0 ? -1L : context == null ? 0L : source.idOf(context);
			String index = backing.getTripleStore()
					.statementEncounterIndexName(
							subject == null ? -1L : source.idOf(subject),
							predicate == null ? -1L : source.idOf(predicate),
							object == null ? -1L : source.idOf(object), contextId);
			Comparator<Statement> order = (left, right) -> {
				for (char component : index.toCharArray()) {
					int comparison = Long.compareUnsigned(componentId(source, left, component),
							componentId(source, right, component));
					if (comparison != 0) {
						return comparison;
					}
				}
				return 0;
			};
			seed.stream()
					.filter(row -> (subject == null || subject.equals(row.getSubject()))
							&& (predicate == null || predicate.equals(row.getPredicate()))
							&& (object == null || object.equals(row.getObject()))
							&& (contexts.length == 0 || Objects.equals(context, row.getContext())))
					.sorted(order)
					.forEach(result::add);
		}
		return result;
	}

	private static List<List<Long>> rawRows(NativeLmdbQuerySource source, Resource subject, IRI predicate,
			Value object, Resource[] contexts) throws Exception {
		List<List<Long>> result = new ArrayList<>();
		Resource[] requests = contexts.length == 0 ? new Resource[] { null } : contexts;
		for (Resource context : requests) {
			if (context != null && (context.isTripleTerm() || source.idOf(context) < 0L)) {
				continue;
			}
			long contextId = contexts.length == 0 ? -1L : context == null ? 0L : source.idOf(context);
			try (RecordIterator records = source.lmdbStatements(subject == null ? -1L : source.idOf(subject),
					predicate == null ? -1L : source.idOf(predicate), object == null ? -1L : source.idOf(object),
					contextId, null)) {
				long[] row;
				while ((row = records.next()) != null) {
					result.add(List.of(row[0], row[1], row[2], row[3]));
				}
			}
		}
		return result;
	}

	private static List<Long> quad(NativeLmdbQuerySource source, Statement row) {
		return List.of(componentId(source, row, 's'), componentId(source, row, 'p'),
				componentId(source, row, 'o'), componentId(source, row, 'c'));
	}

	private static long componentId(NativeLmdbQuerySource source, Statement row, char component) {
		return switch (component) {
		case 's' -> source.idOf(row.getSubject());
		case 'p' -> source.idOf(row.getPredicate());
		case 'o' -> source.idOf(row.getObject());
		case 'c' -> row.getContext() == null ? 0L : source.idOf(row.getContext());
		default -> throw new AssertionError(component);
		};
	}

